from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zeros:
        return [row[:] for row in grid]

    r0 = min(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    kh = max(r for r, c in zeros) - r0 + 1
    kw = max(c for r, c in zeros) - c0 + 1

    def valid(r, c):
        return (0 <= r <= h - kh and 0 <= c <= w - kw and
                all(grid[i][j] in (0, 1, 2)
                    for i in range(r, r + kh)
                    for j in range(c, c + kw)))

    start = (r0, c0)
    dist = {start: 0}
    q = deque([start])

    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (nr, nc) not in dist and valid(nr, nc):
                dist[(nr, nc)] = dist[(r, c)] + 1
                q.append((nr, nc))

    farthest = max(dist.values())
    candidates = [p for p, d in dist.items() if d == farthest]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    def tie_key(p):
        r, c = p
        overlap = sum(
            grid[i][j] == 2
            for i in range(r, r + kh)
            for j in range(c, c + kw)
        )
        if twos:
            tr = sum(x for x, _ in twos) / len(twos)
            tc = sum(y for _, y in twos) / len(twos)
            closeness = -(abs(r - tr) + abs(c - tc))
        else:
            closeness = 0
        return overlap, closeness

    dr, dc = max(candidates, key=tie_key)
